def components(g,bg):
    seen=set(); comps=[]
    import sys
    H=len(g);W=len(g[0]);sys.setrecursionlimit(10**6)
    def find(i,j):
        stack=[(i,j)]; cells=[]
        while stack:
            y,x=stack.pop()
            if (y,x) in seen: continue
            seen.add((y,x)); cells.append((y,x))
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen:
                        if g[ny][nx]!=bg: stack.append((ny,nx))
        return cells
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                cs=find(i,j); comps.append(cs)
